script='''def _trim(shape):
    points = [(r, c) for r, row in enumerate(shape) for c, v in enumerate(row) if v]
    if not points:
        return ()
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    return tuple(tuple(int(shape[r][c]) for c in range(c0, c1 + 1)) for r in range(r0, r1 + 1))


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    left_w = 0
    while left_w < w and grid[0][left_w] == frame:
        left_w += 1
    dividers = [r for r in range(h) if all(grid[r][c] == frame for c in range(left_w))]
    out = [row[:left_w] for row in grid]
    colors = {v for row in grid for v in row[left_w:] if v != 0}
    shapes = {}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(left_w, w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        shapes[color] = _trim(tuple(tuple(int((r, c) in pts) for c in range(c0, c1 + 1)) for r in range(r0, r1 + 1)))
    for top, bottom in zip(dividers, dividers[1:]):
        pattern = _trim(tuple(tuple(int(grid[r][c] == 0) for c in range(1, left_w - 1)) for r in range(top + 1, bottom)))
        color = next((col for col, shape in shapes.items() if shape == pattern), None)
        if color is not None:
            for r in range(top + 1, bottom):
                for c in range(1, left_w - 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
'''
